out=[HEAD]
for num in sorted(CASES,key=int):
    c=CASES[num]; key=f"M14-A{int(num):02d}"
    if 'retired' in c:
        out.append(f"### {key} 范围外\n\n{c['retired']}\n\n"); continue
    out.append(f"### {key} {c['title']}\n\n- 关联需求／原型：{c['rel']}\n- 测试层级：{c['layers']}\n- 前置条件：{c['pre']}\n- 环境与数据：{c['env']}\n- 操作步骤：{c['steps']}\n- 明确预期：{c['expect']}\n- 实际结果、状态、证据／缺陷：{c['result']}\n\n")
out.append(TAIL)
outdir.mkdir(parents=True,exist_ok=True)
(outdir/'测试用例.md').write_text(''.join(out))
applicable=sum('retired' not in c for c in CASES.values())
head_e=EXEC_HEAD
import re
states = {num: re.search(r"^- 状态：([^。（]+)", row, re.M)[1] for num, row in EXEC_ROWS.items()}
assert set(states) == set(CASES)
assert all(state in {"通过", "失败", "未执行", "阻塞", "范围外"} for state in states.values())
assert all(("retired" in CASES[num]) == (state == "范围外") for num, state in states.items())
passed = sum(state == "通过" for state in states.values())
failed = sum(state == "失败" for state in states.values())
pending = sum(state == "未执行" for state in states.values())
blocked = sum(state == "阻塞" for state in states.values())
rate = f"{(100 * passed / applicable if applicable else 0):.2f}"
head_e=re.sub(
    r"当前适用用例 \d+ 条；通过 0、失败 0、未执行 \d+；范围外 \d+ 条，不进入通过率分母。产品整体通过率 0%。",
    f"当前适用用例 {applicable} 条；通过 {passed}、失败 {failed}、未执行 {pending}、阻塞 {blocked}；范围外 {len(CASES)-applicable} 条，不进入通过率分母。产品整体通过率 {rate}%。",
    head_e,
)
e=[head_e]
for num in sorted(EXEC_ROWS,key=int):
    e.append(f"### M14-A{int(num):02d}\n\n{EXEC_ROWS[num]}\n\n")
e.append(EXEC_TAIL)
(outdir/'执行与缺陷记录.md').write_text(''.join(e))
print(json.dumps({'cases':len(CASES),'applicable':applicable,'outside':len(CASES)-applicable}))
